// AP Statistics — original practice bank for the redesigned May 2027 exam.
// All questions and stimulus data are original/synthetic; no College Board questions are copied.
(()=>{"use strict";
const STIMULI={"prob1":{"type":"quantitative","title":"Commuter survey outcomes","description":"A random commuter is classified by whether the trip began before 7:00 a.m. and whether the commuter used public transit. Counts from 400 commuters are shown.","source":"Original synthetic data created for AP Exam Practice.","columns":["","Public transit","Other mode","Total"],"rows":[["Before 7:00 a.m.",72,108,180],["7:00 a.m. or later",44,176,220],["Total",116,284,400]]},"prob2":{"type":"quantitative","title":"Daily equipment failures","description":"For a particular device, X is the number of failures observed during one day. The modeled probability distribution is shown.","source":"Original synthetic probability model created for AP Exam Practice.","columns":["x","0","1","2","3"],"rows":[["P(X = x)",0.5,0.3,0.15,0.05]]},"prob3":{"type":"quantitative","title":"Sampling-mean simulation","description":"A right-skewed population has mean 50 and standard deviation 18. Simulation summaries show repeated simple random samples and their sample means.","source":"Original simulated sampling study created for AP Exam Practice.","columns":["Sample size n","Mean of simulated x̄ values","SD of simulated x̄ values","Approximate shape"],"rows":[[4,50.1,9.0,"right-skewed"],[16,50.0,4.5,"less skewed"],[64,50.0,2.25,"approximately normal"]]},"reg1":{"type":"quantitative","title":"Delivery distance and time","description":"A company records delivery distance x (miles) and delivery time y (minutes) for eight randomly selected local deliveries.","source":"Original synthetic data created for AP Exam Practice.","columns":["Distance x (mi)","2","4","5","7","8","10","12","14"],"rows":[["Time y (min)",18,23,27,31,36,39,46,49]]},"reg2":{"type":"quantitative","title":"Regression output: tree diameter and mass","description":"Software output summarizes a least-squares regression predicting tree mass y (kg) from trunk diameter x (cm) for 32 trees sampled in one managed stand.","source":"Original synthetic regression output created for AP Exam Practice.","columns":["Term","Estimate","SE","t","p-value"],"rows":[["Intercept","−18.4","6.1","−3.02","0.005"],["Diameter","4.72","0.31","15.23","<0.001"],["r²","0.886","","",""],["s","7.8 kg","","",""]]},"reg3":{"type":"visual","title":"Study time and quiz score","description":"Scatterplot of 18 synthetic student observations with a least-squares line. The point near 9 hours and score 61 lies well below the fitted line.","source":"Original synthetic scatterplot created for AP Exam Practice.","image":"assets/ap-statistics-regression-scatter.svg","alt":"Scatterplot of quiz score versus study hours showing a strong positive roughly linear pattern, plus one point near 9 study hours with a score near 61 well below the fitted line."}};
const SPECS=[{"unit":"U1","topicCode":"1.1","skill":"1.A","q":"A city wants to know whether commute time differs between residents who work remotely at least three days per week and residents who do not. Which investigative question is best aligned with that goal?","correct":"How do commute-time distributions compare for frequent remote workers and other city residents?","distractors":["What percentage of all surveyed city residents report working remotely at least three days per week?","Why do some city residents prefer remote work rather than commuting?","Is the average commute time for city residents exactly 30 minutes?"],"e":"The goal names a quantitative response, commute time, and a categorical grouping variable, remote-work status. A comparative question about the two commute-time distributions directly guides both collection and analysis.","variantGroupId":"apstats-v-u1-investigative-comparison"},{"unit":"U1","topicCode":"1.1","skill":"2.A","q":"Researchers ask whether a new tutoring program changes the distribution of algebra test scores. Which pair correctly identifies the explanatory and response variables?","correct":"Tutoring-program participation is explanatory; algebra test score is the response.","distractors":["Algebra test score is the explanatory variable; tutoring-program participation is the categorical response variable.","Student age is explanatory; tutoring-program participation is the response.","The school is explanatory; algebra test score is the response."],"e":"The explanatory variable distinguishes the tutoring conditions being compared, while the response is the quantitative outcome measured after participation. Age or school may matter, but neither is the stated explanatory variable."},{"unit":"U1","topicCode":"1.2","skill":"2.A","q":"A survey records each student's grade level, number of hours slept last night, preferred school-lunch entrée, and backpack mass in kilograms. Which variables are quantitative?","correct":"Hours slept and backpack mass","distractors":["Grade level and hours slept","Preferred entrée category and measured backpack mass in kilograms","Grade level and preferred entrée"],"e":"Hours slept and backpack mass have meaningful numerical magnitudes for which arithmetic comparisons are sensible. Grade level is an ordered label here, and preferred entrée is categorical."},{"unit":"U1","topicCode":"1.2","skill":"4.A","q":"A hospital data set codes discharge destination as 1 = home, 2 = rehabilitation, and 3 = skilled nursing. A student reports that the mean destination code is 1.8. What is the main statistical problem?","correct":"The numerical codes represent categories, so their mean has no meaningful interpretation.","distractors":["The mean should be replaced by a z-score because the codes are standardized.","The destination variable is quantitative because its categories are numbered.","The data cannot be summarized because categorical variables have no useful summaries."],"e":"Assigning numbers to categories does not make the variable quantitative. Counts, proportions, or a bar chart are meaningful, but arithmetic on the arbitrary labels is not."},{"unit":"U1","topicCode":"1.3","skill":"3.B","q":"In a sample of 240 commuters, 96 report using public transit as their primary mode. What is the sample proportion who use public transit?","correct":"0.40","distractors":["0.60","96/100 = 0.96","240/96 = 2.50"],"e":"The sample proportion is the count in the category divided by the total sample size: 96/240 = 0.40. The complement, 0.60, is the proportion using other modes."},{"unit":"U1","topicCode":"1.3","skill":"4.A","q":"A frequency table for 500 households lists 85 with no vehicle, 210 with one vehicle, 160 with two vehicles, and 45 with three or more. Which statement is supported?","correct":"The modal category is one vehicle, containing 42% of the households.","distractors":["The median number of vehicles is exactly one because the largest category is one vehicle.","Most households have at least two vehicles because 160 + 45 exceeds 210.","The mean number of vehicles is 1.33 because the last category can be treated as exactly three."],"e":"The largest count is 210, and 210/500 = 0.42, so one vehicle is the modal category. The open-ended final category prevents an exact mean, and the other numerical claims do not follow."},{"unit":"U1","topicCode":"1.4","skill":"3.A","q":"A school surveys students about one of four preferred after-school activities. Which display is most appropriate for showing the relative frequencies of the four categories?","correct":"A bar chart with one bar for each activity","distractors":["A histogram with touching bars","A scatterplot of activity versus frequency","A normal probability plot"],"e":"Preferred activity is categorical. A bar chart appropriately displays category frequencies or relative frequencies; histograms are for quantitative variables and scatterplots require two quantitative variables."},{"unit":"U1","topicCode":"1.4","skill":"4.A","q":"Two bar charts show the same categorical counts, but one vertical axis begins at 90 instead of 0. What is the most important consequence?","correct":"The truncated axis can visually exaggerate differences among category counts.","distractors":["The category proportions themselves change when the axis is truncated.","The chart becomes a histogram because the baseline is above zero.","The counts can no longer be recovered from labeled bar heights."],"e":"Changing the displayed baseline does not change the data, but it can make modest absolute differences appear much larger. Statistical interpretation should distinguish visual emphasis from the underlying counts."},{"unit":"U1","topicCode":"1.5","skill":"3.A","q":"A teacher wants a display that preserves the individual values of 22 quiz scores while also showing the shape of their distribution. Which display is best suited?","correct":"A dotplot","distractors":["A pie chart","A segmented bar chart","A mosaic plot"],"e":"A dotplot places a mark for each quantitative observation, preserving individual values while revealing clusters, gaps, and shape. The other displays are designed for categorical data."},{"unit":"U1","topicCode":"1.5","skill":"4.A","q":"A histogram of waiting times has most observations between 2 and 8 minutes, with a long tail extending to 35 minutes. Which description best matches the shape?","correct":"Right-skewed","distractors":["Left-skewed","Approximately uniform","Approximately symmetric and bimodal"],"e":"A long tail toward larger values indicates right skew. The direction of skew is named for the tail, not for the side containing most observations."},{"unit":"U1","topicCode":"1.6","skill":"4.C","q":"A distribution of household incomes has one clear peak, a median of $62,000, and a few very large values above $500,000. Which description is most defensible?","correct":"Unimodal and right-skewed, with high-income values that may be outliers","distractors":["Unimodal and left-skewed because the median is below the largest values","Symmetric because there is only one peak","Bimodal because the high-income values form a second distribution by definition"],"e":"A small number of unusually large values creates a right tail and may create high outliers. One dominant peak is consistent with a unimodal distribution; a second mode is not implied by a few extremes."},{"unit":"U1","topicCode":"1.6","skill":"4.A","q":"A dotplot of machine fill weights shows two separated clusters centered near 498 g and 503 g. What feature should be reported before summarizing the data with one mean and one standard deviation?","correct":"The apparent bimodality, because one center and spread may hide two production regimes","distractors":["The data must be normal because both clusters are narrow","The range alone, because shape is irrelevant once the sample size is large","The median must equal 500.5 g because there are two visible clusters"],"e":"Two distinct clusters suggest different underlying conditions or subgroups. A single mean and standard deviation can obscure that structure, so the shape should be described and investigated."},{"unit":"U1","topicCode":"1.7","skill":"3.B","q":"Five delivery times, in minutes, are 18, 20, 21, 21, and 30. What is the mean delivery time?","correct":"22 minutes","distractors":["21 minutes, the median","21.5 minutes, the midpoint of the middle values","30 minutes, the largest observed value"],"e":"The mean is (18 + 20 + 21 + 21 + 30)/5 = 110/5 = 22 minutes. The median is 21 minutes, illustrating the mean's sensitivity to the larger value."},{"unit":"U1","topicCode":"1.7","skill":"4.A","q":"A data set contains a strong high outlier. Which pair of summaries is generally more resistant to that outlier?","correct":"Median and interquartile range","distractors":["Mean and standard deviation computed from the original untransformed observations","Mean and range","Median and standard deviation"],"e":"The median and IQR depend primarily on ranks and the middle half of the data, so a single extreme value usually changes them less than it changes the mean, standard deviation, or range."},{"unit":"U1","topicCode":"1.8","skill":"4.A","q":"In a boxplot, Q1 = 12, the median = 18, and Q3 = 27. Using the 1.5×IQR rule, which value would be flagged as a high outlier?","correct":"52","distractors":["35","40","Q3 + 1.5(IQR) = 49.5"],"e":"The IQR is 27 − 12 = 15, so the upper fence is 27 + 1.5(15) = 49.5. Of the listed values, only 52 exceeds the upper fence."},{"unit":"U1","topicCode":"1.8","skill":"4.A","q":"Two boxplots have the same median, but Group A has a much larger IQR than Group B. Which conclusion is justified from the boxplots?","correct":"The middle 50% of Group A is more spread out than the middle 50% of Group B.","distractors":["Group A has a larger mean than Group B.","Group A has a larger standard deviation than Group B in every possible data set.","Exactly 75% of Group A values exceed the median of Group B."],"e":"The IQR is the distance from Q1 to Q3 and therefore measures spread of the middle 50%. Boxplots alone do not determine means or guarantee a particular standard-deviation ordering."},{"unit":"U1","topicCode":"1.9","skill":"4.C","q":"A runner's time is 68 seconds in a population with mean 72 and standard deviation 2, while a swimmer's time is 55 seconds in a population with mean 60 and standard deviation 4. Which performance is farther below its population mean in standard-deviation units?","correct":"The runner, with z = −2 compared with the swimmer's z = −1.25","distractors":["The swimmer, because 55 is numerically farther from 60 than 68 is from 72","They are equally far below their means because both times are below average","The swimmer, with z = −4/5 compared with the runner's z = −2/72"],"e":"Standardization uses z = (x − μ)/σ. The runner has (68−72)/2 = −2; the swimmer has (55−60)/4 = −1.25. The runner is farther below the relevant mean."},{"unit":"U1","topicCode":"1.9","skill":"4.A","q":"Class A scores are roughly symmetric with median 78 and IQR 10. Class B scores are right-skewed with median 78 and IQR 18. Which comparison is directly supported?","correct":"Same median, but greater middle-half spread in Class B","distractors":["Class B must have the larger mean because it is right-skewed.","Class A must have the larger range because it is symmetric.","The two classes have identical centers and spreads."],"e":"The reported medians are equal, and Class B's larger IQR shows greater spread in its middle 50%. The mean and range cannot be determined from the given summaries."},{"unit":"U1","topicCode":"1.10","skill":"1.A","q":"A researcher plans to estimate the mean weekly exercise time of adults in a county. Which wording most clearly identifies the population parameter in the investigative question?","correct":"What is the mean weekly exercise time, μ, for all adults in the county?","distractors":["What is the mean weekly exercise time, x̄, among the sampled adults?","How many sampled adults exercise at least 150 minutes per week?","Does every adult in the county exercise the same number of minutes?"],"e":"The target parameter is the population mean μ for all county adults. The sample mean x̄ is a statistic computed after sampling and is not the unknown population quantity being estimated."},{"unit":"U1","topicCode":"1.10","skill":"2.A","q":"A study will compare blood-pressure change for two treatments. Which data must be collected to answer the comparative investigative question?","correct":"Record each unit's treatment and blood-pressure change.","distractors":["The treatment labels, without recording the response values","The final blood-pressure values, without recording treatment received","The population mean blood pressure with no unit-level treatment-response pairs"],"e":"A comparison requires knowing both which treatment each unit received and the response measured for that unit. Either piece alone cannot support a treatment comparison."},{"unit":"U1","topicCode":"1.11","skill":"2.A","q":"A university has 8 residence halls. Investigators randomly select 2 halls and survey every resident in those halls. What sampling method is used?","correct":"Cluster random sampling","distractors":["Stratified random sampling","Simple random sampling of individual students","Systematic random sampling"],"e":"The residence halls act as clusters: entire randomly selected groups are surveyed. Stratified sampling would instead sample some individuals from every stratum."},{"unit":"U1","topicCode":"1.11","skill":"2.B","q":"A district wants student opinions represented from elementary, middle, and high schools even though the groups differ greatly in size. Which design best guarantees representation from all three levels?","correct":"Take a random sample separately within each school level.","distractors":["Randomly choose several schools and survey the students present in those schools.","Post an online survey and analyze the first 500 responses.","Select every 50th student from one alphabetized district list without stratifying by level."],"e":"Stratifying by school level and randomly sampling within every level guarantees each level is represented. Cluster, voluntary-response, or unstratified systematic designs do not provide that guarantee."},{"unit":"U1","topicCode":"1.12","skill":"2.A","q":"A news site asks readers to click a link to vote on whether a new tax should pass. Why is the resulting percentage a poor estimate of support among all voters?","correct":"Likely voluntary-response bias from systematic differences between responders and other voters","distractors":["The sample is too large for random sampling to work.","The percentage cannot estimate a population proportion because the response is categorical.","Any online survey automatically has a 50% nonresponse rate."],"e":"Participants self-select into a voluntary-response sample. People with stronger opinions or different online behavior can be overrepresented, producing systematic bias that sample size alone does not remove."},{"unit":"U1","topicCode":"1.12","skill":"2.A","q":"A telephone survey randomly samples registered voters, but only 38% of those contacted complete the interview. Which concern is most relevant?","correct":"Potential nonresponse bias if respondents and nonrespondents differ in opinion","distractors":["Undercoverage because no sampled voter had a chance to respond","Response bias caused solely by using a random sample","Sampling variability disappears because fewer people responded"],"e":"Low response creates potential nonresponse bias when respondents differ systematically from nonrespondents on the variable of interest. Random selection does not eliminate this post-selection problem."},{"unit":"U1","topicCode":"1.13","skill":"2.B","q":"A company tests two package designs. Within each of 20 stores, customers are randomly assigned to see Design A or Design B, and purchase rate is recorded. Why block by store?","correct":"Blocking store can reduce variation caused by store-to-store differences.","distractors":["Blocking makes the customers representative of consumers outside the sampled stores.","Blocking by store is sufficient by itself to establish causation.","Blocking makes random assignment within each store unnecessary."],"e":"Store characteristics can influence the response. Blocking separates that source of variation, while random assignment within each store supports a causal comparison of designs."},{"unit":"U1","topicCode":"1.13","skill":"2.B","q":"In a randomized experiment on a pain treatment, neither participants nor the clinicians evaluating pain know which treatment each participant receives. What is the primary purpose of this double masking?","correct":"To reduce bias from expectations of participants and evaluators","distractors":["To make the treatment groups representative of the national population","To ensure exactly equal sample sizes in the treatment groups","To replace random assignment with a stronger form of control"],"e":"Masking reduces the possibility that expectations influence reported or assessed responses. It does not create population representativeness and does not substitute for random assignment."},{"unit":"U2","topicCode":"2.1","skill":"4.A","q":"Using the commuter table, which comparison provides the clearest evidence about whether departure time and transit use are associated?","correct":"Compare the conditional transit-use percentages within the two departure-time groups.","distractors":["Compare the two marginal departure-time percentages only.","Compare the grand total 400 with the transit total 116.","Compare the raw counts 72 and 176 without accounting for different row totals."],"e":"Association between two categorical variables is assessed by comparing conditional distributions. The relevant transit-use rates are 72/180 = 40% before 7:00 and 44/220 = 20% later, a substantial difference.","stimulusKey":"prob1","statsSetType":"probability"},{"unit":"U2","topicCode":"2.2","skill":"3.B","q":"From the commuter table, what proportion of commuters who departed before 7:00 a.m. used public transit?","correct":"0.40","distractors":["72/400 = 0.18","116/180 ≈ 0.644","116/400 = 0.29"],"e":"This is a conditional relative frequency within the before-7:00 row: 72/180 = 0.40. Dividing by the grand total would instead give the joint relative frequency 72/400 = 0.18.","stimulusKey":"prob1","statsSetType":"probability"},{"unit":"U2","topicCode":"2.6","skill":"3.C","q":"A commuter is selected at random from the table. Given that the commuter used public transit, what is the probability the trip began before 7:00 a.m.?","correct":"72/116, about 0.621","distractors":["72/180, or 0.400, using all before-policy riders as the denominator","72/400, or 0.180","116/400, or 0.290"],"e":"Conditioning on public transit restricts the sample space to the 116 transit users. Of those, 72 departed before 7:00, so the conditional probability is 72/116 ≈ 0.621.","stimulusKey":"prob1","statsSetType":"probability"},{"unit":"U2","topicCode":"2.1","skill":"4.B","q":"In a two-way table, the conditional distribution of preferred payment method is nearly identical for customers under 40 and customers 40 or older. Which conclusion is most appropriate?","correct":"Little evidence of association between age group and payment preference","distractors":["Age group causes customers to choose the same payment method.","The variables are mutually exclusive because their conditional distributions are similar.","The marginal distributions must each be 50%-50%."],"e":"When conditional distributions across groups are similar, the data show little evidence of association. Causation cannot be inferred from a two-way observational summary, and marginal distributions need not be equal."},{"unit":"U2","topicCode":"2.2","skill":"3.B","q":"Among 300 survey respondents, 90 are renters and support a proposal, 60 are renters and oppose it, 75 are homeowners and support it, and 75 are homeowners and oppose it. What is the joint relative frequency of being a renter who supports the proposal?","correct":"0.30","distractors":["135/300 = 0.45","90/150 = 0.60","150/300 = 0.50"],"e":"A joint relative frequency uses the grand total: 90/300 = 0.30. Values such as 90/150 = 0.60 are conditional on renter status rather than joint."},{"unit":"U2","topicCode":"2.6","skill":"3.C","q":"Suppose P(A ∩ B) = 0.18 and P(B) = 0.30. What is P(A | B)?","correct":"0.60","distractors":["0.18(0.30)=0.054","0.30−0.18=0.12","0.30/0.12=2.50"],"e":"Conditional probability is P(A | B) = P(A ∩ B)/P(B) = 0.18/0.30 = 0.60. Multiplying rather than dividing would answer a different probability question."},{"unit":"U2","topicCode":"2.3","skill":"3.C","q":"A simulation uses digits 0–9, with 0–2 representing a defective item and 3–9 representing a nondefective item. Five digits form one simulated shipment. What event should be counted to estimate the probability a shipment has at least two defective items?","correct":"Trials in which at least two of the five digits are 0, 1, or 2","distractors":["Trials in which exactly two digits are 0, 1, or 2","Trials in which the first two digits are both 0, 1, or 2","Trials in which at least two digits are 3 through 9"],"e":"Digits 0–2 model defect with probability 0.3, and a five-digit trial models five items. 'At least two' includes two, three, four, or five defective outcomes, not only exactly two."},{"unit":"U2","topicCode":"2.4","skill":"3.C","q":"A fair six-sided die is rolled twice. What is the probability that at least one roll is a 6?","correct":"11/36","distractors":["1/6","1/36","(5/6)^2 = 25/36"],"e":"Use the complement: P(at least one 6) = 1 − P(no 6 on either roll) = 1 − (5/6)^2 = 11/36. The 1/36 value is the probability of two sixes."},{"unit":"U2","topicCode":"2.4","skill":"3.C","q":"An event E has probability 0.27. What is the probability that E does not occur?","correct":"0.73","distractors":["P(E)=0.27","1−0.63=0.37","1+0.27=1.27"],"e":"An event and its complement exhaust the sample space, so their probabilities sum to 1. Thus P(Eᶜ) = 1 − 0.27 = 0.73."},{"unit":"U2","topicCode":"2.5","skill":"4.B","q":"For events A and B, P(A) = 0.40, P(B) = 0.35, and P(A ∩ B) = 0. Which statement is correct?","correct":"A and B are mutually exclusive.","distractors":["A and B are independent.","P(A ∪ B) = 0.14.","A and B must have equal probabilities."],"e":"Events are mutually exclusive when they cannot occur together, so P(A ∩ B)=0. Because both events have positive probability, independence would require P(A ∩ B)=0.40(0.35)=0.14, not zero."},{"unit":"U2","topicCode":"2.5","skill":"3.C","q":"If P(A) = 0.55, P(B) = 0.30, and A and B are mutually exclusive, what is P(A ∪ B)?","correct":"0.85","distractors":["0.55−0.30=0.25","0.55(0.30)=0.165","1.00 because the events are disjoint"],"e":"For mutually exclusive events, the intersection probability is zero. Therefore P(A ∪ B) = P(A)+P(B) = 0.55+0.30 = 0.85."},{"unit":"U2","topicCode":"2.7","skill":"3.C","q":"Events A and B are independent with P(A)=0.60 and P(B)=0.25. What is P(A ∩ B)?","correct":"0.15","distractors":["0.60+0.25=0.85","0.60−0.25=0.35","0.60/0.25=2.40"],"e":"For independent events, P(A ∩ B)=P(A)P(B)=0.60(0.25)=0.15. Adding the probabilities would not compute the intersection."},{"unit":"U2","topicCode":"2.7","skill":"3.C","q":"Suppose P(A)=0.50, P(B)=0.40, and P(A ∩ B)=0.10. What is P(A ∪ B)?","correct":"0.80","distractors":["0.50+0.40=0.90","0.50−0.40+0.10=0.20","0.50"],"e":"The general addition rule gives P(A ∪ B)=0.50+0.40−0.10=0.80. The intersection must be subtracted because it is included in both marginal probabilities."},{"unit":"U2","topicCode":"2.8","skill":"3.A","q":"For the device-failure model, which statement verifies that the table is a valid discrete probability distribution?","correct":"Probabilities are all in [0,1] and sum to 1.","distractors":["The x-values add to 6 and the probabilities decrease as x increases.","The mean of the x-values equals the largest probability.","Every possible x-value has the same probability."],"e":"A discrete probability distribution must assign a probability in [0,1] to every possible value and the probabilities must sum to 1. Here 0.50+0.30+0.15+0.05=1.","stimulusKey":"prob2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.9","skill":"3.D","q":"For the device-failure model, what is E(X), the expected number of failures per day?","correct":"0.75","distractors":["0.50","1.00","1.50"],"e":"E(X)=ΣxP(X=x)=0(0.50)+1(0.30)+2(0.15)+3(0.05)=0.75. This is a long-run average and need not be a possible integer outcome on a single day.","stimulusKey":"prob2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.10","skill":"4.B","q":"Could the device-failure distribution shown be Binomial(n, p) for some n = 3 and constant p?","correct":"No; the probability ratios do not match a binomial model with three independent equal-p trials.","distractors":["Yes; support on 0, 1, 2, and 3 is sufficient for Binomial n = 3.","Yes; probabilities summing to 1 is sufficient to establish independent equal-p trials.","No; a binomial random variable is restricted to the values 0 and 1."],"e":"Having support 0–3 is not sufficient for a binomial model. Binomial probabilities must arise from three independent binary trials with constant success probability; the displayed probabilities do not have that required form.","stimulusKey":"prob2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.8","skill":"3.A","q":"A game pays X = $0, $5, or $20 with probabilities 0.70, 0.25, and 0.05, respectively. Which quantity is a random variable?","correct":"The dollar amount X paid on one play","distractors":["The fixed probability 0.70","The list of all three probabilities","The statement that the game has three outcomes"],"e":"A random variable assigns a numerical value to the outcome of a random process. The payment X varies from play to play according to the stated probability distribution."},{"unit":"U2","topicCode":"2.9","skill":"4.D","q":"A carnival game's winnings have mean $1.20 and standard deviation $4.50. Which interpretation of the mean is correct?","correct":"The long-run average winnings per play approach $1.20.","distractors":["A player will win exactly $1.20 on most individual plays.","About 68% of plays will be within $1.20 of the mean.","The probability of winning is 1.20."],"e":"The expected value is the long-run average outcome of the random variable. It does not have to be a possible result on any single play and does not itself specify a probability."},{"unit":"U2","topicCode":"2.10","skill":"3.D","q":"For X ~ Binomial(n = 80, p = 0.25), what are the mean and standard deviation of X?","correct":"μ = 20 and σ = √15 ≈ 3.87","distractors":["μ = 20 and σ = √20 ≈ 4.47","μ = 60 and σ = √15 ≈ 3.87","μ = 0.25 and σ = √0.1875 ≈ 0.433"],"e":"For a binomial random variable, μ=np=80(0.25)=20 and σ=√[np(1−p)]=√[80(0.25)(0.75)]=√15≈3.87."},{"unit":"U2","topicCode":"2.11","skill":"3.C","q":"Adult heights are approximately normal with mean 170 cm and standard deviation 6 cm. Approximately what proportion lies between 158 cm and 182 cm?","correct":"About 95%","distractors":["About 68%, the one-standard-deviation empirical-rule value","About 99.7%, the three-standard-deviation empirical-rule value","About 50%, because the interval is centered at the mean"],"e":"The interval 158 to 182 is μ ± 2σ because 170 ± 12 = 170 ± 2(6). By the empirical rule, about 95% of a normal distribution lies within two standard deviations."},{"unit":"U2","topicCode":"2.12","skill":"4.C","q":"The population distribution is strongly right-skewed with finite mean μ and standard deviation σ. What happens to the sampling distribution of x̄ as the sample size increases substantially?","correct":"Center μ, decreasing SD σ/√n, and increasingly normal shape","distractors":["Its mean increases toward the population maximum and its standard deviation remains σ.","Its mean remains μ but its standard deviation increases as σ√n.","Its shape becomes more right-skewed because averaging preserves every population feature."],"e":"For independent sampling, x̄ is centered at μ with standard deviation σ/√n. The central limit theorem says its distribution becomes approximately normal for sufficiently large n even when the population is skewed."},{"unit":"U2","topicCode":"2.3","skill":"3.C","q":"In the sampling-mean simulation, what does the SD 4.5 in the n = 16 row estimate?","correct":"Sample-to-sample variation of x̄ for samples of size 16","distractors":["The within-sample standard deviation for a typical set of 16 observations","The distance from the population mean to a typical sample mean","The probability that a sample mean is different from 50"],"e":"Across repeated samples of size 16, the standard deviation of the simulated sample means estimates the standard error of x̄. It describes sampling variability, not within-sample spread.","stimulusKey":"prob3","statsSetType":"probability"},{"unit":"U2","topicCode":"2.11","skill":"4.C","q":"Which feature of the n = 64 simulation is most consistent with a normal approximation for the sampling distribution of x̄?","correct":"The simulated sample-mean distribution is approximately normal despite the right-skewed population.","distractors":["The simulated center matches each individual population observation.","The simulated standard deviation should equal the population standard deviation 18.","The sample mean is fixed at 50 whenever n = 64."],"e":"The central limit theorem predicts an increasingly normal sampling distribution for x̄ as n grows. Its center stays near 50 while its standard error is much smaller than the population standard deviation.","stimulusKey":"prob3","statsSetType":"probability"},{"unit":"U2","topicCode":"2.12","skill":"3.D","q":"The population standard deviation is 18. What theoretical standard deviation of x̄ is expected for samples of size 64, and how does it compare with the simulation?","correct":"18/√64 = 2.25, matching the simulated value closely","distractors":["18/64 = 0.281, much smaller than the simulated value","18√64 = 144, much larger than the simulated value","18, because averaging does not change sampling variability"],"e":"For independent observations, SD(x̄)=σ/√n=18/8=2.25. The simulation reports 2.25, providing direct agreement with the theoretical sampling-distribution standard deviation.","stimulusKey":"prob3","statsSetType":"probability"},{"unit":"U3","topicCode":"3.1","skill":"4.D","q":"Two unbiased estimators are proposed for the same population proportion. Estimator A has a smaller standard deviation than Estimator B. Which statement is correct?","correct":"Estimator A is more precise because it has less sampling variability.","distractors":["Estimator B is preferable because greater sampling variability offsets possible bias.","Unbiased estimators for the same parameter must have matching sampling distributions.","Estimator A must reproduce the parameter for each sample."],"e":"Unbiasedness concerns the center of a sampling distribution, while precision concerns spread. With both centered at the parameter, the estimator with the smaller standard deviation is more precise."},{"unit":"U3","topicCode":"3.1","skill":"4.D","q":"A statistic T has a sampling distribution centered 4 units above the parameter it estimates. What does this indicate?","correct":"T is biased upward by 4 units.","distractors":["T is unbiased because its sampling distribution has a fixed center.","T has a standard error of 4 units.","T overestimates the parameter in every possible sample."],"e":"Bias is the difference between the expected value of an estimator and the parameter. A center 4 units too high indicates upward bias of 4; individual samples may still fall below the parameter."},{"unit":"U3","topicCode":"3.2","skill":"3.D","q":"A population has proportion p = 0.36. For random samples of size n = 100, what are the mean and standard deviation of the sampling distribution of p̂?","correct":"Mean 0.36 and SD √[0.36(0.64)/100] = 0.048","distractors":["Mean 36 and SD 0.048","Mean 0.36 and SD √[0.36(0.64)] = 0.48","Mean 0.64 and SD √[0.36(0.64)/100] = 0.048"],"e":"For a sample proportion, E(p̂)=p and SD(p̂)=√[p(1−p)/n] when the observations are suitably independent. Substitution gives √0.002304 = 0.048."},{"unit":"U3","topicCode":"3.2","skill":"4.E","q":"For a sample of size 40 from a population with p = 0.08, why is a normal model for p̂ questionable?","correct":"np = 3.2 is too small for the usual large-counts condition.","distractors":["The sample size exceeds 30, which violates the normal condition for proportions.","The population proportion is less than 0.5, so p̂ cannot be approximately normal.","The standard error can be computed, so a normal model is automatically valid."],"e":"A normal approximation for p̂ generally requires both np and n(1−p) to be sufficiently large. Here np = 3.2 is small, so the sampling distribution can be strongly skewed."},{"unit":"U3","topicCode":"3.3","skill":"2.C","q":"A random sample of 250 voters contains 145 who support a bond issue. Which procedure is appropriate for estimating the population proportion who support it?","correct":"A one-sample z-interval for a population proportion","distractors":["A one-sample t-interval for a population mean","A two-sample z-interval for a difference in proportions","A chi-square test for independence"],"e":"There is one random sample, one binary response, and the target parameter is a single population proportion. That matches a one-sample z-interval for a proportion."},{"unit":"U3","topicCode":"3.3","skill":"3.E","q":"A sample proportion is p̂ = 0.58 with estimated standard error 0.031. Using z* = 1.96, which 95% confidence interval is closest?","correct":"(0.519, 0.641)","distractors":["(0.549, 0.611)","(0.500, 0.660)","(0.420, 0.740)"],"e":"The margin of error is 1.96(0.031)=0.06076. Thus the interval is 0.58 ± 0.06076, or approximately (0.519, 0.641)."},{"unit":"U3","topicCode":"3.4","skill":"4.F","q":"A 95% confidence interval for the proportion of all customers satisfied with a service is (0.71, 0.79). Which interpretation is correct?","correct":"We are 95% confident that 0.71 to 0.79 contains the population satisfaction proportion.","distractors":["There is a 95% probability that this fixed interval contains the fixed population proportion.","Exactly 95% of customers have satisfaction values between 0.71 and 0.79.","If the survey is repeated, 95% of future sample proportions will lie inside this one interval."],"e":"The confidence procedure has long-run capture rate 95%; after the interval is computed, the parameter is fixed and the interval either contains it or not. The standard contextual wording is '95% confident.'"},{"unit":"U3","topicCode":"3.4","skill":"4.G","q":"A 90% confidence interval for a population proportion is (0.42, 0.49). A manager claims that a majority of the population supports a proposal. What does the interval suggest?","correct":"It does not support a majority because the entire interval is below 0.50.","distractors":["The claim is proved because 0.49 is close to 0.50.","The claim is supported because a 90% interval excludes 0.","No claim can ever be assessed using a confidence interval."],"e":"A majority corresponds to p > 0.50. Because the entire interval is below 0.50, the data are inconsistent with a majority at the confidence level represented by the interval."},{"unit":"U3","topicCode":"3.5","skill":"2.E","q":"A manufacturer claims that fewer than 2% of its batteries fail during the warranty period. Which hypotheses appropriately test the claim?","correct":"H₀: p = 0.02 versus Hₐ: p < 0.02","distractors":["H₀: p < 0.02 versus Hₐ: p = 0.02","H₀: p̂ = 0.02 versus Hₐ: p̂ < 0.02","H₀: p = 0.02 versus Hₐ: p > 0.02"],"e":"Hypotheses are statements about the population parameter p, not the sample statistic p̂. The phrase 'fewer than' determines a left-tailed alternative p < 0.02."},{"unit":"U3","topicCode":"3.5","skill":"4.E","q":"A one-sample z-test for a proportion uses H₀: p = 0.40 with n = 50. Which condition check should use the null value 0.40?","correct":"The large-counts check: 50(0.40) and 50(0.60)","distractors":["The 10% condition, which becomes 50 < 0.40N","The randomization condition, which requires 40% of subjects be randomly assigned","The significance level, which must equal 0.40"],"e":"For a one-proportion significance test, the null model determines the standard error and large-counts check, so np₀ and n(1−p₀) are used. Random sampling and the 10% condition are assessed separately."},{"unit":"U3","topicCode":"3.6","skill":"4.F","q":"A hypothesis test reports p-value = 0.018. Which interpretation is correct?","correct":"Assuming H₀, a result at least this extreme in the Hₐ direction has probability 0.018.","distractors":["The probability that the null hypothesis is true is 0.018.","The probability that the alternative hypothesis is false is 0.018.","Exactly 1.8% of the population contradicts the null hypothesis."],"e":"A p-value is computed under the assumption that H₀ is true. It measures how unusual the observed statistic, or something more extreme in the alternative direction, would be under that null model."},{"unit":"U3","topicCode":"3.6","skill":"4.D","q":"Two studies test the same null and alternative hypotheses. Study A has p-value 0.004 and Study B has p-value 0.08. Which statement is justified?","correct":"Study A provides stronger evidence against H₀ than Study B.","distractors":["Study A proves H₀ is false while Study B proves H₀ is true.","Study B has a larger effect size because its p-value is larger.","The p-values show that Study A's population parameter is 0.004."],"e":"Smaller p-values indicate data less compatible with the null model, so Study A provides stronger evidence against H₀. P-values do not by themselves prove hypotheses or measure effect size."},{"unit":"U3","topicCode":"3.7","skill":"3.E","q":"In a test of H₀: p = 0.50, a sample of n = 200 has p̂ = 0.57. What is the z test statistic?","correct":"About 1.98","distractors":["About 0.14","About 2.80","About 4.04"],"e":"Under H₀, SE = √[0.50(0.50)/200] ≈ 0.03536. Thus z = (0.57−0.50)/0.03536 ≈ 1.98. The positive statistic reflects that the observed sample proportion is above the null value."},{"unit":"U3","topicCode":"3.7","skill":"4.G","q":"A test of H₀: p = 0.30 versus Hₐ: p > 0.30 gives p-value 0.032 at α = 0.05. What conclusion is appropriate?","correct":"Reject H₀; there is convincing statistical evidence that the population proportion exceeds 0.30.","distractors":["Fail to reject H₀ because 0.032 is larger than the null proportion 0.30.","Accept H₀ and conclude the population proportion equals 0.30.","Reject H₀ and conclude every individual in the population has probability above 0.30."],"e":"Because 0.032 < 0.05, the result is statistically significant and H₀ is rejected. The conclusion should be stated as evidence about the population proportion, not as certainty."},{"unit":"U3","topicCode":"3.8","skill":"2.D","q":"For H₀: p = 0.60 versus Hₐ: p > 0.60, what is a Type I error?","correct":"Concluding that p > 0.60 when in fact p = 0.60","distractors":["Failing to conclude p > 0.60 when in fact p > 0.60","Concluding p = 0.60 after the null hypothesis has been proven","Using a sample proportion different from 0.60"],"e":"A Type I error is rejecting a true null hypothesis. Here that means claiming the population proportion exceeds 0.60 when the null value 0.60 is actually correct."},{"unit":"U3","topicCode":"3.8","skill":"2.D","q":"For a fixed alternative value, which change generally increases the power of a significance test without changing the significance level?","correct":"Increase the sample size.","distractors":["Decrease the sample size.","Make the null and alternative parameter values closer together.","Increase sampling variability while keeping n fixed."],"e":"A larger sample size reduces standard error, making a real departure from H₀ easier to detect. Power also tends to increase for larger effect sizes, while added variability reduces power."},{"unit":"U3","topicCode":"3.9","skill":"3.D","q":"Independent populations have p₁ = 0.40 and p₂ = 0.25. Samples of sizes n₁ = 100 and n₂ = 150 are taken. What is the mean of the sampling distribution of p̂₁ − p̂₂?","correct":"0.15","distractors":["0 under an equal-proportions null","(0.40+0.25)/2=0.325","0.40+0.25=0.65"],"e":"The expected value of a difference in sample proportions is the difference in population proportions: E(p̂₁−p̂₂)=p₁−p₂=0.40−0.25=0.15."},{"unit":"U3","topicCode":"3.9","skill":"3.D","q":"For independent samples, which expression is the standard deviation of p̂₁ − p̂₂ when population proportions p₁ and p₂ are known?","correct":"√[p₁(1−p₁)/n₁ + p₂(1−p₂)/n₂]","distractors":["√[(p₁−p₂)(1−p₁+p₂)/(n₁+n₂)]","p₁(1−p₁)/n₁ + p₂(1−p₂)/n₂","√[p₁(1−p₁)/n₁] − √[p₂(1−p₂)/n₂]"],"e":"For independent sample proportions, variances add when taking a difference. Therefore the variance is the sum of the two component variances and the standard deviation is the square root of that sum."},{"unit":"U3","topicCode":"3.10","skill":"2.C","q":"Two independent random samples estimate the difference p₁ − p₂ between population proportions. Which interval procedure is appropriate?","correct":"A two-sample z-interval for p₁ − p₂","distractors":["A paired t-interval for a mean difference","A one-sample z-interval for a single proportion","A chi-square goodness-of-fit interval"],"e":"The target is the difference between two population proportions based on independent samples, so the appropriate method is a two-sample z-interval for p₁−p₂."},{"unit":"U3","topicCode":"3.10","skill":"3.E","q":"Sample 1 has p̂₁ = 0.62 with n₁ = 200, and Sample 2 has p̂₂ = 0.54 with n₂ = 180. What is the point estimate for p₁ − p₂?","correct":"0.08","distractors":["(0.62+0.54)/2=0.58","0.54−0.62=−0.08","0.62+0.54=1.16"],"e":"The point estimate for a difference in population proportions is the corresponding difference in sample proportions: p̂₁−p̂₂=0.62−0.54=0.08."},{"unit":"U3","topicCode":"3.11","skill":"4.F","q":"A 95% confidence interval for p₁ − p₂ is (0.03, 0.14). Which interpretation is appropriate?","correct":"We are 95% confident that p₁ is between 0.03 and 0.14 greater than p₂.","distractors":["There is a 95% probability that p₁ − p₂ changes from 0.03 to 0.14.","Exactly 95% of individual observations in population 1 exceed those in population 2.","The two population proportions are equal because 0 lies near the interval."],"e":"The interval estimates the fixed population difference p₁−p₂. Because the entire interval is positive, it indicates population 1's proportion is plausibly 0.03 to 0.14 higher than population 2's."},{"unit":"U3","topicCode":"3.11","skill":"4.G","q":"A confidence interval for p₁ − p₂ is (−0.04, 0.09). What does it imply about a claim that the two population proportions differ?","correct":"Including 0 means the interval does not give convincing evidence of a difference.","distractors":["The interval proves the proportions are exactly equal.","The positive endpoint proves p₁ > p₂.","The negative endpoint proves p₁ < p₂."],"e":"A zero difference is among the plausible parameter values in the interval. Thus the interval does not supply convincing evidence of a nonzero difference, although it does not prove equality."},{"unit":"U3","topicCode":"3.12","skill":"2.E","q":"Researchers compare response rates p₁ and p₂ for two populations and suspect p₁ is lower. Which hypotheses are appropriate?","correct":"H₀: p₁ − p₂ = 0 versus Hₐ: p₁ − p₂ < 0","distractors":["H₀: p̂₁ − p̂₂ = 0 versus Hₐ: p̂₁ − p̂₂ < 0","H₀: p₁ − p₂ < 0 versus Hₐ: p₁ − p₂ = 0","H₀: p₁ + p₂ = 0 versus Hₐ: p₁ + p₂ < 0"],"e":"Hypotheses concern population parameters. 'Population 1 is lower' translates to p₁−p₂<0, while the null represents no population difference."},{"unit":"U3","topicCode":"3.12","skill":"4.E","q":"For a two-proportion z-test of H₀: p₁ = p₂, which proportion is used in the standard error of the test statistic?","correct":"The pooled sample proportion because H₀ assumes a common population proportion","distractors":["Each sample proportion separately, exactly as in a confidence interval","The arithmetic mean (p̂₁+p̂₂)/2 regardless of sample sizes","The null difference 0 used as though it were a probability"],"e":"Under H₀ the groups share one common proportion, estimated by pooling successes across both samples. A confidence interval does not impose equality and therefore uses separate sample proportions in its standard error."},{"unit":"U3","topicCode":"3.13","skill":"3.E","q":"Two samples yield x₁=84 of n₁=120 successes and x₂=63 of n₂=110. For testing H₀: p₁=p₂, what pooled proportion should be used?","correct":"147/230 ≈ 0.639","distractors":["84/120 = 0.700","63/110 ≈ 0.573","(0.700+0.573)/2 ≈ 0.636"],"e":"The pooled estimate combines successes and observations under the common-proportion null: (84+63)/(120+110)=147/230≈0.639. An unweighted average of sample proportions is not generally the pooled estimate."},{"unit":"U3","topicCode":"3.13","skill":"4.G","q":"A two-proportion z-test gives z = 2.45 and a two-sided p-value of 0.014. At α = 0.01, what is the appropriate decision?","correct":"Fail to reject H₀ because 0.014 > 0.01.","distractors":["Reject H₀ because |2.45| is greater than 2.","Reject H₀ because 0.014 < 0.05 even though α = 0.01.","Accept H₀ and conclude the proportions are identical."],"e":"The stated decision rule compares the p-value with the chosen significance level. Since 0.014 exceeds 0.01, the result is not significant at 1%, so H₀ is not rejected."},{"unit":"U3","topicCode":"3.14","skill":"2.C","q":"A random sample classifies each person by political affiliation (three categories) and preferred news source (four categories). Which procedure tests whether the two categorical variables are associated in the population?","correct":"A chi-square test of independence","distractors":["A one-proportion z-test","A two-sample t-test","A chi-square goodness-of-fit test"],"e":"With one random sample and two categorical variables recorded on each individual, a chi-square test of independence assesses whether the variables are associated in the population."},{"unit":"U3","topicCode":"3.14","skill":"2.C","q":"Two independent random samples classify people into the same four response categories. Which inference procedure compares the category distributions across the two populations?","correct":"A chi-square test for homogeneity","distractors":["A chi-square test of independence for one sample with two variables","A two-sample t test for population means","A two-proportion z test restricted to two categories"],"e":"With separate random samples from two populations and one categorical response recorded in the same categories, a chi-square test for homogeneity compares the population distributions."},{"unit":"U3","topicCode":"3.14","skill":"3.C","q":"In a two-way table, a row total is 80, a column total is 45, and the grand total is 200. Under independence, what is the expected count in their intersection?","correct":"18","distractors":["16","22.5","36"],"e":"For a chi-square test of independence or homogeneity, an expected count is (row total)(column total)/(grand total). Thus 80(45)/200=18."},{"unit":"U3","topicCode":"3.15","skill":"3.E","q":"A chi-square statistic is the sum of which quantities across all cells?","correct":"(observed − expected)^2 / expected","distractors":["observed − expected","(observed − expected)^2 / observed","expected^2 / observed"],"e":"Each cell contributes the squared discrepancy between observed and expected counts divided by the expected count. Summing those nonnegative contributions gives the chi-square statistic."},{"unit":"U3","topicCode":"3.14","skill":"2.E","q":"For a chi-square test of independence between two categorical variables, which null hypothesis is appropriate?","correct":"The two categorical variables are independent in the population.","distractors":["The two variables have exactly equal sample counts in every cell.","The two variables have a linear correlation of zero.","Every category has the same population proportion."],"e":"A chi-square test of independence begins with the population-level claim that the two categorical variables are independent; the alternative states that they are associated."},{"unit":"U3","topicCode":"3.15","skill":"2.D","q":"In a chi-square test of independence, what would a Type I error mean?","correct":"Concluding the variables are associated when they are actually independent.","distractors":["Concluding the variables are independent when they are actually associated.","Computing an expected count that differs from its observed count.","Using a sample size that is larger than necessary."],"e":"A Type I error is rejecting a true null hypothesis. Here the null states independence, so the error is claiming an association that does not actually exist in the population."},{"unit":"U4","topicCode":"4.9","skill":"2.C","q":"Two independent random samples provide quantitative outcomes and the population standard deviations are unknown. Which test compares the population means?","correct":"A two-sample t test for μ₁−μ₂","distractors":["A paired t test on matched differences","A two-proportion z test","A chi-square test for homogeneity"],"e":"Independent quantitative samples with unknown population standard deviations call for a two-sample t procedure when comparing the two population means."},{"unit":"U4","topicCode":"4.1","skill":"2.A","q":"A researcher wants to use a sample mean to learn about a population mean. Which data-collection plan best supports the usual sampling-distribution model?","correct":"Select a random sample of individuals from the population.","distractors":["Select only individuals with values near the population center.","Let volunteers decide whether they want to be measured.","Choose consecutive individuals from one convenient location."],"e":"Random sampling supports treating observations as representative draws from the population, which is the design basis for using the sampling distribution of the sample mean in inference."},{"unit":"U4","topicCode":"4.2","skill":"2.C","q":"Which procedure is appropriate for estimating a population mean when σ is unknown and observations come from one random sample?","correct":"A one-sample t interval for μ","distractors":["A one-proportion z interval","A paired t test","A chi-square test of independence"],"e":"A single quantitative sample with unknown population standard deviation calls for a one-sample t interval, provided independence and shape/sample-size conditions are reasonable."},{"unit":"U4","topicCode":"4.10","skill":"2.D","q":"For a two-sample mean test, what change generally reduces the chance of a Type II error when a meaningful difference truly exists?","correct":"Increase the sample sizes in the two groups.","distractors":["Decrease both sample sizes.","Increase measurement variability.","Use less informative measurements while keeping n fixed."],"e":"Larger samples reduce standard errors and increase power, so a meaningful true difference is more likely to be detected and a Type II error becomes less likely."},{"unit":"U4","topicCode":"4.2","skill":"2.D","q":"A researcher wants a smaller margin of error for a confidence interval for a population mean without changing the confidence level. Which design change helps?","correct":"Increase the sample size.","distractors":["Decrease the sample size.","Use a more variable population if possible.","Replace the sample mean with a sample proportion."],"e":"Increasing sample size reduces the standard error s/√n, so the confidence interval becomes more precise while keeping the same confidence level."},{"unit":"U4","topicCode":"4.3","skill":"2.D","q":"A researcher is planning a confidence interval for a population mean and wants the interval to be more precise at the same confidence level. Which design change helps?","correct":"Increase the random-sample size.","distractors":["Decrease the random-sample size.","Collect measurements with greater variability if possible.","Replace quantitative measurements with category labels."],"e":"Increasing the sample size reduces the standard error of the sample mean, which reduces the margin of error and gives a more precise confidence interval at the same confidence level."},{"unit":"U4","topicCode":"4.4","skill":"2.E","q":"A company claims the mean fill volume is 500 mL. An auditor suspects underfilling. Which hypotheses are appropriate?","correct":"H0: μ=500 versus Ha: μ<500","distractors":["H0: x̄=500 versus Ha: x̄<500","H0: μ<500 versus Ha: μ=500","H0: μ=500 versus Ha: μ≠500"],"e":"Hypotheses are about the population mean μ. Because the auditor specifically suspects underfilling, the alternative is μ<500 and the null uses equality at the claimed value."},{"unit":"U4","topicCode":"4.4","skill":"2.D","q":"For a fixed true difference from the null value, which change generally increases the power of a one-sample test for a population mean?","correct":"Use a larger random sample.","distractors":["Use a smaller random sample.","Choose a smaller true effect while holding everything else fixed.","Increase the standard error of the estimator."],"e":"A larger sample decreases standard error, making a fixed departure from the null easier to distinguish from sampling variation and therefore increasing statistical power."},{"unit":"U4","topicCode":"4.5","skill":"3.E","q":"A sample gives x̄=53, s=8, n=16 for testing H0: μ=50. What is the t statistic?","correct":"1.5","distractors":["0.375","3.0","6.0"],"e":"The standard error is 8/√16=2. The test statistic is (53−50)/2=1.5, measuring the observed mean 1.5 standard errors above the null value."},{"unit":"U4","topicCode":"4.5","skill":"2.D","q":"For H₀: μ=50 versus Hₐ: μ>50, what is a Type I error?","correct":"Concluding μ>50 when the true population mean is 50.","distractors":["Failing to conclude μ>50 when the true mean exceeds 50.","Obtaining a sample mean different from 50.","Using a significance level smaller than 0.05."],"e":"A Type I error means rejecting a true null hypothesis. If μ really equals 50, the error is concluding from the sample that the population mean is greater than 50."},{"unit":"U4","topicCode":"4.6","skill":"3.D","q":"Two independent sample means have standard errors based on s1=10,n1=25 and s2=12,n2=36. What is the estimated standard error of x̄1−x̄2?","correct":"√8 ≈ 2.83","distractors":["√2 ≈ 1.41","22/61 ≈ 0.36","8"],"e":"For independent samples, estimated variances add: 10^2/25 + 12^2/36 = 4+4=8, giving standard error √8≈2.83."},{"unit":"U4","topicCode":"4.6","skill":"2.B","q":"A study will compare mean outcomes for two treatments. Which design creates two independent samples rather than paired data?","correct":"Randomly assign different participants to the two treatment groups.","distractors":["Give both treatments to every participant and compare within-person differences.","Match each participant with the same participant measured twice.","Record two measurements from each participant without separating them by treatment."],"e":"Using different participants in independently formed treatment groups creates independent samples. Repeated or matched measurements on the same individuals instead create paired data."},{"unit":"U4","topicCode":"4.7","skill":"2.C","q":"Which procedure estimates μ1−μ2 from two independent random samples when both population standard deviations are unknown?","correct":"A two-sample t interval for μ1−μ2","distractors":["A paired t interval","A two-proportion z interval","A chi-square interval"],"e":"Two independent quantitative samples with unknown population standard deviations call for a two-sample t interval. A paired procedure would instead analyze within-pair differences."},{"unit":"U4","topicCode":"4.7","skill":"3.E","q":"A 95% confidence interval for μ1−μ2 is reported as (1.4,6.6). What is the point estimate?","correct":"4.0","distractors":["2.6","5.2","8.0"],"e":"A standard confidence interval is symmetric around its point estimate. The midpoint is (1.4+6.6)/2=4.0, which estimates μ1−μ2."},{"unit":"U4","topicCode":"4.7","skill":"2.B","q":"The same patients have blood pressure measured before and after treatment. Which data structure should the analysis preserve?","correct":"Pair each patient’s before and after measurements and analyze the within-patient differences.","distractors":["Treat all before values and all after values as independent samples.","Convert each measurement to a categorical success or failure.","Discard one measurement from every patient to ensure independence."],"e":"The two measurements on each patient are naturally dependent. A paired analysis keeps that matching and performs inference on the distribution of within-patient differences."},{"unit":"U4","topicCode":"4.8","skill":"2.D","q":"A researcher is planning a confidence interval for the difference between two population means. Which change generally makes the interval narrower at the same confidence level?","correct":"Increase the sample sizes in both groups.","distractors":["Decrease the sample sizes in both groups.","Increase the variability of measurements in both groups.","Use more variable measurement methods while keeping sample sizes fixed."],"e":"Larger independent samples reduce the standard error of the difference in sample means, which reduces the margin of error and produces a narrower confidence interval at the same confidence level."},{"unit":"U4","topicCode":"4.9","skill":"2.E","q":"Researchers suspect a new treatment lowers mean recovery time relative to standard care. Which alternative hypothesis matches μnew−μstandard?","correct":"Ha: μnew−μstandard<0","distractors":["Ha: μnew−μstandard>0","Ha: μnew−μstandard=0","Ha: x̄new−x̄standard<0"],"e":"A lower mean for the new treatment corresponds to μnew<μstandard, or equivalently μnew−μstandard<0. Hypotheses concern population means, not sample means."},{"unit":"U4","topicCode":"4.9","skill":"4.E","q":"Two groups were formed by random assignment of 20 subjects to each treatment. Their quantitative responses show no extreme outliers. What supports use of a two-sample t test?","correct":"Independent randomized groups and reasonably well-behaved sample distributions","distractors":["Knowing both population standard deviations exactly","Having categorical rather than quantitative responses","Forcing both sample means to be equal under H0"],"e":"Random assignment supports independence between treatment groups, and the absence of extreme outliers helps justify t procedures at these sample sizes. Population standard deviations need not be known."},{"unit":"U4","topicCode":"4.10","skill":"3.E","q":"For testing H0: μ1−μ2=0, the observed difference is 6 and its estimated standard error is 2. What is the t statistic?","correct":"3","distractors":["12","0.33","8"],"e":"The test statistic standardizes the observed difference relative to the null difference: (6−0)/2=3. Thus the sample difference is three estimated standard errors from the null."},{"unit":"U4","topicCode":"4.10","skill":"4.G","q":"A two-sample t test produces a very small p-value, but the study used volunteers rather than random sampling. Which conclusion is safest?","correct":"There is evidence of a difference for the studied groups, but generalization to a broader population is limited.","distractors":["The small p-value automatically makes the sample representative.","The result proves the treatment caused the difference in every population.","Volunteer sampling has no effect on scope of inference."],"e":"A small p-value addresses evidence against the null under the model, but nonrandom sampling limits how broadly results can be generalized. Scope of inference depends on study design as well as significance."},{"unit":"U4","topicCode":"4.2","skill":"2.D","q":"Holding confidence level and sample variability fixed, what happens to the margin of error for a mean when sample size is quadrupled?","correct":"It is cut in half.","distractors":["It doubles.","It is unchanged.","It is divided by four."],"e":"Standard error for a mean is proportional to 1/√n. Quadrupling n doubles √n, so the standard error and hence the margin of error are halved."},{"unit":"U4","topicCode":"4.4","skill":"2.D","q":"Which change generally increases the power of a test for a population mean when the true effect size is unchanged?","correct":"Increasing the sample size","distractors":["Decreasing the sample size","Using a smaller effect in the population","Increasing the standard error"],"e":"Larger samples reduce standard error, making a fixed departure from the null easier to detect. That increases the probability of rejecting a false null hypothesis, which is statistical power."},{"unit":"U4","topicCode":"4.5","skill":"4.D","q":"A result is statistically significant with a mean difference of only 0.2 units in a very large sample. What additional question should be asked?","correct":"Whether a 0.2-unit difference is practically important in context","distractors":["Whether statistical significance proves a large effect","Whether the p-value must therefore exceed 0.50","Whether the null hypothesis can now be accepted"],"e":"Large samples can make very small effects statistically detectable. Statistical significance should therefore be considered alongside the practical importance of the estimated effect size."},{"unit":"U4","topicCode":"4.7","skill":"2.B","q":"Measurements are taken before and after an intervention on the same 24 people. How should the data be analyzed?","correct":"Use a paired t procedure on the 24 within-person differences.","distractors":["Treat the before and after measurements as two independent samples.","Use a chi-square test because there are two conditions.","Use a one-proportion z procedure."],"e":"Each after measurement is naturally paired with the before measurement from the same person. Analyzing within-person differences accounts for that dependence and is the appropriate paired design."},{"unit":"U4","topicCode":"4.10","skill":"4.F","q":"A 99% confidence interval is wider than a 95% interval from the same sample. Why?","correct":"Higher confidence requires a larger critical value and therefore a larger margin of error.","distractors":["Higher confidence uses a smaller standard error.","The sample mean changes when confidence level changes.","A 99% interval always uses fewer observations."],"e":"For a fixed sample, the standard error and point estimate do not change with confidence level. Greater confidence requires a larger critical multiplier, producing a wider interval."},{"unit":"U5","topicCode":"5.3","skill":"3.B","q":"A least-squares line is ŷ=20+1.5x. What response is predicted when x=4?","correct":"26","distractors":["21.5","6","80"],"e":"Substituting x=4 gives ŷ=20+1.5(4)=26. The fitted value is the model prediction for the response at that explanatory-variable value."},{"unit":"U5","topicCode":"5.4","skill":"3.B","q":"A model predicts y=42 for an observation whose actual value is 37. What is the residual?","correct":"−5","distractors":["5","79","0.88"],"e":"Residual equals observed minus predicted, so 37−42=−5. A negative residual means the observed response lies below the fitted regression line."},{"unit":"U5","topicCode":"5.5","skill":"3.B","q":"If sx=4, sy=10, and r=0.60, what is the least-squares slope?","correct":"1.5","distractors":["0.24","6.0","4.0"],"e":"For simple linear regression, b1=r(sy/sx)=0.60(10/4)=1.5. The slope combines the standardized association with the scales of y and x."},{"unit":"U5","topicCode":"5.5","skill":"3.B","q":"A least-squares line has slope 1.5 and passes through (x̄,ȳ)=(4,26). What is its intercept?","correct":"20","distractors":["32","22","5.5"],"e":"The least-squares line passes through (x̄,ȳ). Using 26=b0+1.5(4) gives b0=20. This result follows from the least-squares model and the definitions of fitted values, residuals, and regression summaries."},{"unit":"U5","topicCode":"5.5","skill":"4.D","q":"Why is predicting at x=45 risky when the observed x-values range only from 2 to 14?","correct":"It is extrapolation far beyond the observed data range.","distractors":["Regression predictions are invalid whenever x is positive.","The least-squares line cannot be evaluated numerically at x=45.","A large x-value automatically makes the residual zero."],"e":"A fitted relationship is supported by the range of x-values actually observed. Extending it far beyond that range assumes the same pattern continues, an assumption that may be unjustified."},{"unit":"U2","topicCode":"2.1","skill":"3.C","q":"Using the commuter table, what is P(public transit)?","correct":"116/400 = 0.29","distractors":["72/400 = 0.18","116/284 ≈ 0.408","284/400 = 0.71"],"e":"The marginal total for public transit is 116 out of 400 commuters, so the unconditional probability is 116/400=0.29.","stimulusKey":"prob1","stimulusGroupId":"apstats-prob-set-1","statsSetType":"probability"},{"unit":"U2","topicCode":"2.2","skill":"4.D","q":"Using the commuter table, compare public-transit use for trips before 7:00 a.m. with trips at 7:00 a.m. or later.","correct":"The earlier group has the higher conditional proportion: 72/180=0.40 versus 44/220=0.20.","distractors":["Both groups have the same conditional proportion, 0.29.","The later group is higher because 176 exceeds 108.","The comparison cannot be made from a two-way table."],"e":"Conditional proportions compare within each departure-time group. Public transit is 72/180=0.40 before 7 and 44/220=0.20 later, so the earlier group has the higher rate.","stimulusKey":"prob1","stimulusGroupId":"apstats-prob-set-1","statsSetType":"probability"},{"unit":"U2","topicCode":"2.6","skill":"3.C","q":"Using the commuter table, what is P(before 7:00 a.m. | public transit)?","correct":"72/116 ≈ 0.621","distractors":["72/180 = 0.400","116/400 = 0.290","180/400 = 0.450"],"e":"Conditioning on public transit restricts the denominator to the 116 public-transit commuters. Of those, 72 traveled before 7, giving 72/116≈0.621.","stimulusKey":"prob1","stimulusGroupId":"apstats-prob-set-1","statsSetType":"probability"},{"unit":"U5","topicCode":"5.1","skill":"4.A","q":"Using the delivery data, which description best summarizes the association between distance and time?","correct":"A very strong positive roughly linear association","distractors":["A strong negative curved association","No visible association","A perfect horizontal relationship"],"e":"As distance increases, delivery time also increases and the points lie close to an upward-sloping line, indicating a very strong positive approximately linear relationship.","stimulusKey":"reg1","stimulusGroupId":"apstats-reg-set-1","statsSetType":"regression"},{"unit":"U5","topicCode":"5.2","skill":"3.B","q":"For the delivery data, software gives r≈0.996. What is the best interpretation of r²?","correct":"About 99.1% of the variability in delivery time is explained by its linear relationship with distance.","distractors":["About 99.6% of deliveries take the same amount of time.","Distance causes 99.1% of delivery time.","The regression slope is approximately 0.991."],"e":"Squaring r gives about 0.991. In simple linear regression, r² is the proportion of response variation accounted for by the fitted linear relationship with the explanatory variable.","stimulusKey":"reg1","stimulusGroupId":"apstats-reg-set-1","statsSetType":"regression"},{"unit":"U5","topicCode":"5.3","skill":"3.B","q":"For the delivery data, the least-squares line is ŷ=13.10+2.649x. What is the predicted time for a 9-mile delivery?","correct":"About 36.9 minutes","distractors":["About 23.8 minutes","About 49.0 minutes","About 11.8 minutes"],"e":"Substituting x=9 gives ŷ=13.10+2.649(9)=36.941, so the predicted delivery time is about 36.9 minutes.","stimulusKey":"reg1","stimulusGroupId":"apstats-reg-set-1","statsSetType":"regression"},{"unit":"U5","topicCode":"5.4","skill":"4.D","q":"Regression software reports residual standard deviation s=7.8 kg. What does that quantity describe?","correct":"A typical vertical prediction error is about 7.8 kg.","distractors":["The slope changes by 7.8 kg per centimeter.","Exactly 7.8% of observations are outliers.","The correlation is 7.8."],"e":"The residual standard deviation summarizes the typical size of prediction errors in response-variable units. Here observed masses typically differ from fitted values by roughly 7.8 kg.","stimulusKey":"reg2","stimulusGroupId":"apstats-reg-set-2","statsSetType":"regression"},{"unit":"U5","topicCode":"5.5","skill":"4.D","q":"Regression software reports r²=0.886 for predicting tree mass from diameter. What does this mean?","correct":"About 88.6% of the sample variation in tree mass is explained by the fitted linear relationship with diameter.","distractors":["Diameter explains exactly 88.6 kg of mass.","The correlation must equal 0.886.","The slope is 88.6% per centimeter."],"e":"The coefficient of determination is a proportion of response variation explained by the fitted linear model. It is not a slope, a response amount, or the correlation itself.","stimulusKey":"reg2","stimulusGroupId":"apstats-reg-set-2","statsSetType":"regression"},{"unit":"U2","topicCode":"2.8","skill":"3.C","q":"Using the device-failure distribution, what is P(X≥1)?","correct":"0.50","distractors":["0.30","0.20","0.75"],"e":"The complement event is X=0, which has probability 0.50. Therefore P(X≥1)=1−0.50=0.50. The stated reasoning follows directly from the statistical model and the quantities supplied in the problem.","stimulusKey":"prob2","stimulusGroupId":"apstats-prob-set-2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.9","skill":"3.D","q":"Using the device-failure distribution, what is E(X)?","correct":"0.75","distractors":["0.50","1.50","2.00"],"e":"The expected value is the probability-weighted average: 0(0.50)+1(0.30)+2(0.15)+3(0.05)=0.75 failures.","stimulusKey":"prob2","stimulusGroupId":"apstats-prob-set-2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.9","skill":"4.D","q":"Given that at least one device fails, what is P(X=2)?","correct":"0.30","distractors":["0.15","0.20","0.50"],"e":"Conditioning on X≥1 changes the denominator to 0.50. Thus P(X=2|X≥1)=0.15/0.50=0.30. The stated reasoning follows directly from the statistical model and the quantities supplied in the problem.","stimulusKey":"prob2","stimulusGroupId":"apstats-prob-set-2","statsSetType":"probability"},{"unit":"U2","topicCode":"2.3","skill":"4.B","q":"Which simulated sampling distribution has the smallest standard deviation?","correct":"The distribution for n=64","distractors":["The distribution for n=4","The distribution for n=16","All three have the same standard deviation"],"e":"The simulation reports standard deviations 9, 4.5, and 2.25 for n=4,16,64 respectively, so the largest sample size has the smallest sampling variability.","stimulusKey":"prob3","stimulusGroupId":"apstats-prob-set-3","statsSetType":"probability"},{"unit":"U2","topicCode":"2.11","skill":"4.C","q":"Which simulated sampling distribution is closest to normal in shape?","correct":"The distribution for n=64","distractors":["The distribution for n=4","The distribution for n=16 only because its mean is 50","None can approach normal from a skewed population"],"e":"As sample size grows, the central limit theorem makes the sampling distribution of the sample mean more nearly normal; the n=64 simulation is described as approximately normal.","stimulusKey":"prob3","stimulusGroupId":"apstats-prob-set-3","statsSetType":"probability"},{"unit":"U2","topicCode":"2.12","skill":"3.D","q":"Across the three simulations, what value is the sampling distribution of x̄ centered near?","correct":"50","distractors":["2.25","18","64"],"e":"The sample mean is an unbiased estimator of the population mean, so each simulated sampling distribution is centered near μ=50 despite differing sample sizes.","stimulusKey":"prob3","stimulusGroupId":"apstats-prob-set-3","statsSetType":"probability"},{"unit":"U5","topicCode":"5.3","skill":"4.D","q":"Regression output gives a diameter coefficient of 4.72. How should that slope be interpreted?","correct":"Predicted mass rises about 4.72 kg per additional centimeter of diameter.","distractors":["Predicted diameter rises 4.72 cm per kilogram of mass.","The correlation between diameter and mass equals 4.72.","A tree with zero diameter has predicted mass 4.72 kg."],"e":"The diameter coefficient is the fitted slope, so it gives the change in predicted response, measured in kilograms, for each one-centimeter increase in diameter.","stimulusKey":"reg2","stimulusGroupId":"apstats-reg-set-2","statsSetType":"regression"},{"unit":"U5","topicCode":"5.1","skill":"4.A","q":"Using the scatterplot, which description best fits the overall pattern?","correct":"Strong positive, roughly linear association","distractors":["Strong negative, roughly linear association","No association between the variables","Perfect positive association with no unusual point"],"e":"Most points follow an upward, approximately linear pattern, although one point near nine study hours has an unusually low quiz score.","stimulusKey":"reg3","stimulusGroupId":"apstats-reg-set-3","statsSetType":"regression"},{"unit":"U5","topicCode":"5.2","skill":"4.B","q":"What effect does the unusually low point near nine study hours most likely have on correlation?","correct":"It weakens the positive correlation.","distractors":["It makes the correlation exactly 1.","It changes a positive association to a negative one.","It has no possible effect on correlation."],"e":"The point lies well below the prevailing positive linear pattern, increasing scatter around a line and therefore reducing the magnitude of the positive correlation.","stimulusKey":"reg3","stimulusGroupId":"apstats-reg-set-3","statsSetType":"regression"},{"unit":"U5","topicCode":"5.4","skill":"3.B","q":"Relative to a fitted line through the main pattern, what sign would the residual of the unusually low point have?","correct":"Negative","distractors":["Positive","Zero","Undefined"],"e":"A residual is observed minus predicted. The unusual point lies below the fitted line, so its observed quiz score is less than its predicted score and the residual is negative.","stimulusKey":"reg3","stimulusGroupId":"apstats-reg-set-3","statsSetType":"regression"},{"unit":"U1","topicCode":"1.1","skill":"1.A","q":"A school wants to compare commute times for bus riders and students driven to school. Which question is statistical?","correct":"How do the two groups’ commute times compare?","distractors":["Is one named student a bus rider this morning?","What time did the first bus arrive today?","Does the school own exactly twelve buses?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.1","skill":"1.A","q":"A coach wants to study free-throw performance on the team. Which investigative question anticipates variability?","correct":"What is the distribution of players’ free-throw percentages?","distractors":["Did one player make the final free throw?","Is the regulation free-throw line fifteen feet long?","How many baskets are in the gym?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.10","skill":"1.A","q":"A city planner is interested in household recycling. Which question is appropriate for a statistical investigation?","correct":"What proportion of households recycle weekly?","distractors":["Does one specified household recycle this week?","Where is the nearest recycling center located?","Is recycling collection scheduled for Tuesday?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.11","skill":"1.A","q":"A researcher will sample adults to study sleep duration. Which question is statistical?","correct":"How many hours of sleep do adults typically report?","distractors":["Did one selected adult sleep eight hours last night?","What time does the researcher go to bed?","Is midnight earlier than one in the morning?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.12","skill":"1.A","q":"A principal wants to study student wait times in the lunch line. Which question is statistical?","correct":"How are lunch-line wait times distributed among students?","distractors":["Did Maya wait exactly six minutes today?","What food is listed first on today’s menu?","Does the cafeteria open at eleven o’clock?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.13","skill":"1.A","q":"A company is evaluating battery life for a new phone model. Which question calls for data with variability?","correct":"How is battery life distributed across phones?","distractors":["Did one phone last exactly twelve hours?","Is the battery labeled with its model number?","Does the phone include a charging cable?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.1","skill":"1.A","q":"A teacher wants to compare quiz performance between two class periods. Which question is statistical?","correct":"How do quiz scores differ across periods?","distractors":["Did one student earn a score of eighty?","Which room hosts the first class period?","Was the quiz printed on white paper?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.10","skill":"1.A","q":"A health researcher studies weekly exercise among local adults. Which question is statistical?","correct":"How is weekly exercise time distributed?","distractors":["Did one adult exercise yesterday afternoon?","Is the recreation center open on Sunday?","Does a week contain seven calendar days?"],"e":"The question asks about a population or process and anticipates variation across observations, so collecting data from multiple observational units can reveal a distribution, comparison, or population proportion."},{"unit":"U1","topicCode":"1.11","skill":"2.A","q":"A school wants a simple random sample of 80 students from a roster of 1,600. Which method best implements that design?","correct":"Number all 1,600 students and use a random-number generator to select 80 distinct numbers.","distractors":["Survey the first 80 students entering the cafeteria.","Ask for 80 volunteers through a schoolwide message.","Choose the 80 students with the highest attendance."],"e":"A simple random sample gives every set of 80 students an equal chance to be selected, which can be implemented by numbering the full roster and randomly choosing distinct labels."},{"unit":"U1","topicCode":"1.12","skill":"2.B","q":"A website posts a poll and lets any visitor choose whether to respond. What sampling problem is most immediate?","correct":"Voluntary-response bias because people with stronger opinions may be more likely to participate.","distractors":["Undercoverage because every visitor is forced to respond.","A matched-pairs design because responses come in pairs.","Blocking because visitors are randomly assigned to groups."],"e":"A voluntary-response sample is self-selected. People motivated to answer can differ systematically from those who do not respond, so the resulting sample may not represent the target population."}];
const COUNTS={};
const Q=SPECS.map((s,i)=>{const unit=s.unit;COUNTS[unit]=(COUNTS[unit]||0)+1;const c=i%4;const opts=s.distractors.slice();opts.splice(c,0,s.correct);const q={id:'apstats-'+unit.toLowerCase()+'-'+String(COUNTS[unit]).padStart(3,'0'),unit,topicCode:s.topicCode,skill:s.skill,type:'s',q:s.q,o:opts,c:[c],e:s.e,statsSetType:s.statsSetType||'standalone'};if(s.variantGroupId)q.variantGroupId=s.variantGroupId;if(s.stimulusGroupId)q.stimulusGroupId=s.stimulusGroupId;if(s.stimulusKey)q.stimulus=STIMULI[s.stimulusKey];return q;});
window.QUESTIONS_AP_STATISTICS=Q;})();
